var n=`0566-norin`;var t=`world-0566`;var o=`UZ`;var s=`central-asia`;var r=4;var a=130;var l={en:`Norin`,ua:`Нарин`};var m={en:`A traditional dish from Uzbekistan, centered on beef chuck, yellow onion, all-purpose flour, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Узбекистан. Основні складники: яловича лопатка, жовта цибуля, пшеничне борошно універсальне, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 105 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 105 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:105,i:[[`beef-chuck`,550,`g`],[`water`,1350,`ml`],[`yellow-onion`,160,`g`]]},{en:`Cook the listed ingredients in simmering water for about 14 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 14 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:14,i:[[`all-purpose-flour`,320,`g`],[`chicken-egg`,1,`pcs`],[`water`,130,`ml`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-black-pepper`,null,`to_taste`],[`sunflower-oil`,40,`ml`]]}];var d={slug:n,id:t,country:`UZ`,region:s,servings:4,minutes:130,title:l,text:m,steps:g};export{o as country,d as default,t as id,a as minutes,s as region,r as servings,n as slug,g as steps,m as text,l as title};